def transform(grid):
    g=[r[:] for r in grid]
    # Fill internal holes in every horizontal color run, and extend vertical marker lines upward,
    # using the color of the horizontal band where each marker crosses it.
    h,w=len(g),len(g[0])
    bands={}
    for r,row in enumerate(g):
        nz=[c for c,v in enumerate(row) if v]
        if len(nz)>=2:
            # only horizontal band if broad footprint
            for c in range(min(nz),max(nz)+1):
                if g[r][c]==0:
                    # dominant color, typically single band color
                    vals=[g[r][x] for x in nz]
                    from collections import Counter
                    g[r][c]=Counter(vals).most_common(1)[0][0]
            bands[r]=[g[r][min(nz)]]
    for c in range(w):
        nz=[r for r in range(h) if g[r][c]]
        if nz and min(nz)>=h-3:
            # marker above: draw vertical with colors of horizontal bands it encounters, else nearest stripe color
            color=g[max(nz)][c]
            for r in range(min(nz)-1,-1,-1):
                if r in bands:
                    color=g[r][c] if g[r][c] else color
                g[r][c]=color
    return g
